def ensure_dir(p):
    os.makedirs(p, exist_ok=True)


def canonical_path(p):
    return os.path.realpath(os.path.abspath(os.path.expanduser(p)))


def sha256_file(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def allow_hash(path):
    h = hashlib.sha256()
    h.update(canonical_path(path).encode())
    h.update(b"\0")
    try:
        with open(path, "rb") as f:
            for chunk in iter(lambda: f.read(65536), b""):
                h.update(chunk)
    except FileNotFoundError:
        pass
    return h.hexdigest()


def deny_hash(path):
    return hashlib.sha256(canonical_path(path).encode()).hexdigest()


def allow_path(cfg, rc):
    return os.path.join(cfg.data_dir, "allow", allow_hash(rc))


def deny_path(cfg, rc):
    return os.path.join(cfg.data_dir, "deny", deny_hash(rc))


def is_whitelisted(cfg, rc):
    rp = canonical_path(rc)
    if cfg.whitelist_exact.get(rp):
        return True
    for p in cfg.whitelist_prefix:
        if rp.startswith(p):
            return True
    return False


def auth_status(cfg, rc):
    if is_whitelisted(cfg, rc):
        return 0
    if os.path.exists(deny_path(cfg, rc)):
        return 2
    ap = allow_path(cfg, rc)
    if os.path.exists(ap):
        try:
            with open(ap, "r", encoding="utf-8") as f:
                stored = f.read().strip()
            if canonical_path(stored) == canonical_path(rc):
                return 0
        except Exception:
            return 0
    return 1


