on_git_branch() {{
  has git || return 1
  git rev-parse --absolute-git-dir >/dev/null 2>&1 || return 1
  [[ -z "$1" ]] && return 0
  local b; b=$(git branch --show-current)
  if [[ "$1" = -r ]]; then [[ "$b" =~ $2 ]]; else [[ "$b" = "$1" ]]; fi
}}

__main__() {{
  for lib in "$direnv_config_dir/lib/"*.sh; do source "$lib"; done
  if [[ -f "$direnv_config_dir/direnvrc" ]]; then source "$direnv_config_dir/direnvrc" >&2;
  elif [[ -f "$HOME/.direnvrc" ]]; then source "$HOME/.direnvrc" >&2; fi
  "$@"
}}
'''


def evaluate_envrc(rc, base_env, cfg):
    env = sanitize_env_for_child(base_env)
    env["DIRENV_IN_ENVRC"] = "1"
    env.setdefault("DIRENV_CONFIG", cfg.config_dir)
    env.setdefault("XDG_CONFIG_HOME", os.path.dirname(cfg.config_dir) if cfg.config_dir.endswith("/direnv") else os.path.dirname(cfg.config_dir))
    script = r'''
exec 3>&1
exec 1>&2
__direnv_dump() {
  local __ret=$?
  /usr/bin/env -0 >&3
  trap - EXIT
  exit $__ret
}
trap __direnv_dump EXIT
''' + stdlib_script(find_self_path()) + "\n"
    if cfg.strict_env:
        script += "set -euo pipefail\n"
    script += "__main__ source " + shlex.quote(rc) + "\n"
    try:
        proc = subprocess.run([cfg.bash_path, "-c", script], input=(b"" if cfg.disable_stdin else None), env=env,
                              stdout=subprocess.PIPE, stderr=subprocess.PIPE, cwd=os.path.dirname(rc))
    except FileNotFoundError:
        raise RuntimeError(f"fork/exec {cfg.bash_path}: no such file or directory")
    outenv = {}
    for part in proc.stdout.split(b"\0"):
        if not part or b"=" not in part:
            continue
        k, v = part.split(b"=", 1)
        try:
            ks = k.decode(); vs = v.decode()
        except UnicodeDecodeError:
            ks = k.decode("utf-8", "surrogateescape"); vs = v.decode("utf-8", "surrogateescape")
        outenv[ks] = vs
    for k in list(IGNORED_DIFF_VARS):
        if k in ("DIRENV_IN_ENVRC", "SHLVL", "_", "OLDPWD"):
            outenv.pop(k, None)
    return proc.returncode, outenv, proc.stderr.decode("utf-8", "replace")


def load_target_env(rc, base_env, cfg, for_exec=False):
    """Return (status, target_env, stderr_text, error_message). status: ok, blocked, denied, error"""
    a = auth_status(cfg, rc)
    state_env = dict(base_env)
    # If blocked/denied/eval error, reset to base plus bookkeeping for the candidate rc.
    state_env["DIRENV_DIR"] = "-" + os.path.dirname(rc)
    state_env["DIRENV_FILE"] = rc
    state_env["DIRENV_WATCHES"] = build_watches(cfg, rc)
    tmp_state = {"base": base_env, "rc": rc, "dir": os.path.dirname(rc)}
    state_env["DIRENV_DIFF"] = encode_obj(tmp_state)
    if a == 1:
        return "blocked", state_env, "", f"{rc} is blocked. Run `direnv allow` to approve its content"
    if a == 2:
        return "denied", state_env, "", None
    if rc.endswith("/.env") or os.path.basename(rc) == ".env":
        try:
            _res, env2 = dotenv_parse(rc, base_env)
        except Exception as ex:
            return "error", state_env, "", str(ex)
        target = dict(env2)
        target["DIRENV_DIR"] = "-" + os.path.dirname(rc)
        target["DIRENV_FILE"] = rc
        target["DIRENV_WATCHES"] = build_watches(cfg, rc)
        target["DIRENV_DIFF"] = encode_obj({"base": base_env, "rc": rc, "dir": os.path.dirname(rc)})
        if for_exec:
            target["DIRENV_IN_ENVRC"] = "1"
        return "ok", target, "", None
    # .envrc
    cfg.log_status(f"loading {rc}")
    try:
        ret, env_after, stderr_text = evaluate_envrc(rc, base_env, cfg)
    except RuntimeError as ex:
        return "error", state_env, "", str(ex)
    if cfg.strict_env and ret != 0:
        return "error", state_env, stderr_text, f"exit status {ret}"
    # In non-strict mode direnv tolerates the final status of the sourced file.
    target = dict(env_after if env_after else base_env)
    target.pop("DIRENV_IN_ENVRC", None)
    target["DIRENV_DIR"] = "-" + os.path.dirname(rc)
    target["DIRENV_FILE"] = rc
    target["DIRENV_WATCHES"] = build_watches(cfg, rc)
    target["DIRENV_DIFF"] = encode_obj({"base": base_env, "rc": rc, "dir": os.path.dirname(rc)})
    if for_exec:
        target["DIRENV_IN_ENVRC"] = "1"
    return "ok", target, stderr_text, None


def command_export(args):
    shell = args[0] if args else ""
    if shell not in EXPORT_SHELLS:
        die(f"unknown target shell '{shell}'")
    cfg = Config()
    cur = current_env_dict()
    base = get_base_env(cur)
    rc = find_rc_from(os.getcwd(), cfg)
    if not rc:
        if cur.get("DIRENV_DIFF"):
            target = dict(base)
            changes = compute_changes(cur, target)
            out = render_exports(changes, shell)
            if out:
                sys.stdout.write(out)
                cfg.log_status("unloading")
        return 0
    status, target, stderr_text, errmsg = load_target_env(rc, base, cfg, for_exec=False)
    if stderr_text:
        sys.stderr.write(stderr_text)
    changes = compute_changes(cur, target)
    out = render_exports(changes, shell)
    if out:
        sys.stdout.write(out)
    if status == "blocked":
        eprint(f"{ANSI_RED}direnv: error {errmsg}{ANSI_RESET}")
        return 1
    if status == "error":
        eprint(f"{ANSI_RED}direnv: error {errmsg}{ANSI_RESET}")
        return 1
    if status == "ok" and out and not cfg.hide_env_diff:
        dl = diff_log(base, target)
        if dl:
            cfg.log_status("export " + " ".join(dl))
    return 0


def command_exec(args):
    if len(args) < 2:
        if len(args) == 0:
            die("missing DIR and COMMAND arguments")
        else:
            die("missing COMMAND argument")
    directory = canonical_path(args[0])
    if not os.path.exists(directory):
        die(f"stat {directory}: no such file or directory")
    cmd = args[1:]
    cfg = Config()
    base = {k: v for k, v in current_env_dict().items() if k not in INTERNAL_VARS}
    oldcwd = os.getcwd()
    try:
        os.chdir(directory)
        rc = find_rc_from(directory, cfg)
        if rc:
            status, target, stderr_text, errmsg = load_target_env(rc, base, cfg, for_exec=True)
            if stderr_text:
                sys.stderr.write(stderr_text)
            if status == "blocked":
                eprint(f"{ANSI_RED}direnv: error {errmsg}{ANSI_RESET}")
                return 1
            if status == "error":
                eprint(f"{ANSI_RED}direnv: error {errmsg}{ANSI_RESET}")
                return 1
            env = sanitize_env_for_child(target if status == "ok" else base)
        else:
            env = sanitize_env_for_child(base)
        exe = cmd[0]
        if "/" not in exe:
            found = shutil.which(exe, path=env.get("PATH"))
            if not found:
                die(f"command '{exe}' not found on PATH '{env.get('PATH','')}'")
            exe = found
        try:
            proc = subprocess.run([exe] + cmd[1:], env=env, cwd=directory)
            return proc.returncode
        except FileNotFoundError:
            die(f"command '{cmd[0]}' not found")
    finally:
        try:
            os.chdir(oldcwd)
        except Exception:
            pass


def command_allow(args, deny=False):
    cfg = Config()
    try:
        rc = resolve_rc_arg(args[0] if args else None, cfg)
    except FileNotFoundError as ex:
        die(str(ex))
    if not rc or not os.path.exists(rc):
        die(".envrc file not found")
    if deny:
        write_marker(deny_path(cfg, rc), rc)
        remove_path_quiet(allow_path(cfg, rc))
    else:
        write_marker(allow_path(cfg, rc), rc)
        remove_path_quiet(deny_path(cfg, rc))
    return 0


def command_reload(args):
    cfg = Config()
    rc = find_rc_from(os.getcwd(), cfg)
    if not rc:
        die(".envrc not found")
    return 0


def command_prune(args):
    cfg = Config()
    allow_dir = os.path.join(cfg.data_dir, "allow")
    if not os.path.isdir(allow_dir):
        die(f"open {allow_dir}: no such file or directory")
    for dname in ["allow"]:  # original keeps deny markers; prune stale allows.
        d = os.path.join(cfg.data_dir, dname)
        if not os.path.isdir(d):
            continue
        for name in os.listdir(d):
            p = os.path.join(d, name)
            try:
                with open(p, "r", encoding="utf-8") as f:
                    target = f.read().strip()
                if target and not os.path.exists(target):
                    os.remove(p)
            except Exception:
                pass
    return 0


def command_edit(args):
    cfg = Config()
    try:
        rc = resolve_rc_arg(args[0] if args else None, cfg)
    except FileNotFoundError as ex:
        die(str(ex))
    if not rc:
        rc = os.path.join(os.getcwd(), ".envrc")
    editor = os.environ.get("EDITOR") or os.environ.get("VISUAL")
    if not editor:
        log_error_msg("$EDITOR not found.")
        die("could not find a default editor in the PATH")
    cmd = shlex.split(editor) + [rc]
    ret = subprocess.call(cmd)
    if ret != 0:
        die(f"exit status {ret}")
    return command_allow([rc], deny=False)


def fmt_time(path):
    try:
        t = os.path.getmtime(path)
    except OSError:
        t = 0
    return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(t))


def print_rc_status(prefix, rc, cfg):
    print(f"{prefix} RC path {rc}")
    for p in [rc, allow_path(cfg, rc), deny_path(cfg, rc)]:
        try:
            rel = os.path.relpath(p, os.path.dirname(rc))
        except Exception:
            rel = p
        print(f"{prefix} watch: \"{rel}\" - {fmt_time(p)}")
    print(f"{prefix} RC allowed {auth_status(cfg, rc)}")
    print(f"{prefix} RC allowPath {allow_path(cfg, rc)}")


def command_status(args):
    cfg = Config()
    cur = current_env_dict()
    found = find_rc_from(os.getcwd(), cfg)
    loaded = cur.get("DIRENV_FILE")
    if args and args[0] == "--json":
        obj = {
            "config": {"ConfigDir": cfg.config_dir, "SelfPath": find_self_path()},
            "state": {
                "foundRC": ({"allowed": auth_status(cfg, found), "path": found} if found else None),
                "loadedRC": ({"allowed": auth_status(cfg, loaded), "path": loaded} if loaded and os.path.exists(loaded) else None),
            },
        }
        print(json.dumps(obj, indent=2))
        return 0
    print(f"direnv exec path {find_self_path()}")
    print(f"DIRENV_CONFIG {cfg.config_dir}")
    print(f"bash_path {cfg.bash_path}")
    print(f"disable_stdin {str(cfg.disable_stdin).lower()}")
    print(f"warn_timeout {cfg.warn_timeout}")
    print("whitelist.prefix [" + " ".join(cfg.whitelist_prefix) + "]")
    if cfg.whitelist_exact:
        body = " ".join(f"{k}:true" for k in cfg.whitelist_exact)
        print(f"whitelist.exact map[{body}]")
    else:
        print("whitelist.exact map[]")
    if loaded and os.path.exists(loaded):
        print_rc_status("Loaded", loaded, cfg)
    else:
        print("No .envrc or .env loaded")
    if found:
        print_rc_status("Found", found, cfg)
    else:
        print("No .envrc or .env found")
    return 0


def command_version(args):
    if not args:
        print(VERSION)
        return 0
    desired = args[0]
    def parse(v):
        v = v.strip()
        if v.startswith("v"):
            v = v[1:]
        m = re.match(r'^(\d+)(?:\.(\d+))?(?:\.(\d+))?', v)
        if not m:
            return None
        return tuple(int(x or 0) for x in m.groups())
    d = parse(desired)
    if d is None:
        die(f"v{desired.lstrip('v')} is not a valid semver version")
    cur = parse(VERSION)
    if cur < d:
        want = desired if desired.startswith("v") else "v" + desired
        die(f"current version v{VERSION} is older than the desired version {want}")
    return 0


def command_log(args):
    if len(args) != 2:
        die("invalid arguments")
    typ, msg = args
    if typ == "--status":
        eprint(f"{ANSI_RESET}direnv: {msg}")
    elif typ == "--error":
        eprint(f"{ANSI_RED}direnv: {msg}{ANSI_RESET}")
    else:
        die(f"invalid log-type '{typ}'")
    return 0


