#!/usr/bin/env python3
import base64
import hashlib
import json
import os
import re
import shlex
import shutil
import signal
import stat
import subprocess
import sys
import tempfile
import time
import urllib.request
import zlib
from pathlib import Path

VERSION = "2.37.1"
SUPPORTED_SHELLS = ["bash", "zsh", "fish", "tcsh", "elvish", "pwsh", "murex", "json", "vim", "gha", "gzenv", "systemd"]
EXPORT_SHELLS = set(SUPPORTED_SHELLS)
HOOK_SHELLS = {"bash", "zsh", "fish", "tcsh", "elvish", "pwsh", "murex"}
INTERNAL_VARS = {"DIRENV_DIFF", "DIRENV_DIR", "DIRENV_FILE", "DIRENV_WATCHES"}
IGNORED_DIFF_VARS = {"DIRENV_IN_ENVRC", "PWD", "OLDPWD", "SHLVL", "_"}
STATE_PREFIX = "PYDIRENV1:"
ANSI_RESET = "\033[0m"
ANSI_RED = "\033[31m"


def eprint(s=""):
    sys.stderr.write(str(s) + "\n")


def die(msg, code=1):
    eprint(f"{ANSI_RED}direnv: error {msg}{ANSI_RESET}")
    raise SystemExit(code)


def log_error_msg(msg):
    eprint(f"{ANSI_RED}direnv: {msg}{ANSI_RESET}")


def find_self_path():
    try:
        return os.path.realpath(sys.argv[0]) if os.path.isabs(sys.argv[0]) else os.path.realpath(os.path.abspath(sys.argv[0]))
    except Exception:
        return os.path.abspath(sys.argv[0])


def getenv_path(name, default_suffix):
    val = os.environ.get(name, "")
    if val:
        return os.path.expanduser(val)
    home = os.environ.get("HOME", str(Path.home()))
    return os.path.join(home, default_suffix)


class Config:
    def __init__(self):
        self.config_dir = os.environ.get("DIRENV_CONFIG") or os.path.join(getenv_path("XDG_CONFIG_HOME", ".config"), "direnv")
        self.data_dir = os.path.join(getenv_path("XDG_DATA_HOME", ".local/share"), "direnv")
        self.cache_dir = os.path.join(getenv_path("XDG_CACHE_HOME", ".cache"), "direnv")
        self.bash_path = "/usr/bin/bash" if os.path.exists("/usr/bin/bash") else (shutil.which("bash") or "/bin/bash")
        self.disable_stdin = False
        self.load_dotenv = False
        self.strict_env = False
        self.warn_timeout = "5s"
        self.hide_env_diff = False
        self.log_format = None
        self.log_filter = None
        self.whitelist_prefix = []
        self.whitelist_exact = {}
        self._load()

    def _expand(self, s):
        return os.path.abspath(os.path.expanduser(str(s)))

    def _load(self):
        path = os.path.join(self.config_dir, "direnv.toml")
        if not os.path.exists(path):
            # historical name, accepted by older direnv; harmless convenience
            old = os.path.join(self.config_dir, "config.toml")
            path = old if os.path.exists(old) else path
        if not os.path.exists(path):
            return
        data = {}
        try:
            try:
                import tomllib  # type: ignore
                with open(path, "rb") as f:
                    data = tomllib.load(f)
            except Exception:
                data = self._tiny_toml(path)
        except Exception as ex:
            # The real command reports config parse errors, but most workflows prefer continuing.
            eprint(f"{ANSI_RED}direnv: error loading config: {ex}{ANSI_RESET}")
            return
        glob = data.get("global", {}) if isinstance(data, dict) else {}
        if isinstance(glob, dict):
            if "bash_path" in glob:
                self.bash_path = str(glob["bash_path"])
            if "disable_stdin" in glob:
                self.disable_stdin = bool(glob["disable_stdin"])
            if "load_dotenv" in glob:
                self.load_dotenv = bool(glob["load_dotenv"])
            if "strict_env" in glob:
                self.strict_env = bool(glob["strict_env"])
            if "warn_timeout" in glob:
                self.warn_timeout = str(glob["warn_timeout"])
            if "hide_env_diff" in glob:
                self.hide_env_diff = bool(glob["hide_env_diff"])
            if "log_format" in glob:
                self.log_format = str(glob["log_format"])
            if "log_filter" in glob:
                self.log_filter = str(glob["log_filter"])
        wl = data.get("whitelist", {}) if isinstance(data, dict) else {}
        if isinstance(wl, dict):
            pref = wl.get("prefix", []) or []
            exact = wl.get("exact", []) or []
            self.whitelist_prefix = [self._expand(x) for x in pref]
            mp = {}
            for x in exact:
                p = self._expand(x)
                if os.path.isdir(p) or not os.path.basename(p).startswith("."):
                    # direnv treats directory entries as directory/.envrc
                    if os.path.isdir(p) or os.path.splitext(p)[1] == "":
                        p = os.path.join(p, ".envrc")
                mp[p] = True
            self.whitelist_exact = mp

    def _tiny_toml(self, path):
        # Small fallback parser for the simple config forms used by direnv docs.
        out = {}
        sec = None
        with open(path, "r", encoding="utf-8") as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith("#"):
                    continue
                if line.startswith("[") and line.endswith("]"):
                    sec = line[1:-1].strip()
                    out.setdefault(sec, {})
                    continue
                if "=" not in line or sec is None:
                    continue
                k, v = line.split("=", 1)
                k = k.strip(); v = v.strip()
                if "#" in v and not v.startswith(('"', "'")):
                    v = v.split("#", 1)[0].strip()
                val = None
                if v.lower() in ("true", "false"):
                    val = (v.lower() == "true")
                elif v.startswith("[") and v.endswith("]"):
                    body = v[1:-1].strip()
                    arr = []
                    if body:
                        for part in re.finditer(r'''"((?:[^"\\]|\\.)*)"|'((?:[^'\\]|\\.)*)'|([^,]+)''', body):
                            item = part.group(1) if part.group(1) is not None else part.group(2) if part.group(2) is not None else part.group(3)
                            if item is not None:
                                arr.append(bytes(item.strip().strip('"\''), "utf-8").decode("unicode_escape"))
                    val = arr
                elif (v.startswith('"') and v.endswith('"')) or (v.startswith("'") and v.endswith("'")):
                    val = bytes(v[1:-1], "utf-8").decode("unicode_escape") if v.startswith('"') else v[1:-1]
                else:
                    val = v
                out.setdefault(sec, {})[k] = val
        return out

    def log_status(self, message):
        fmt = self.log_format
        if fmt == "-":
            return
        if self.log_filter:
            try:
                if re.search(self.log_filter, message):
                    return
            except re.error:
                pass
        if fmt:
            try:
                eprint(fmt % message)
            except Exception:
                eprint(fmt.replace("%s", message))
        else:
            eprint(f"{ANSI_RESET}direnv: {message}")


def ensure_dir(p):
    os.makedirs(p, exist_ok=True)


def canonical_path(p):
    return os.path.realpath(os.path.abspath(os.path.expanduser(p)))


def sha256_file(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def allow_hash(path):
    h = hashlib.sha256()
    h.update(canonical_path(path).encode())
    h.update(b"\0")
    try:
        with open(path, "rb") as f:
            for chunk in iter(lambda: f.read(65536), b""):
                h.update(chunk)
    except FileNotFoundError:
        pass
    return h.hexdigest()


def deny_hash(path):
    return hashlib.sha256(canonical_path(path).encode()).hexdigest()


def allow_path(cfg, rc):
    return os.path.join(cfg.data_dir, "allow", allow_hash(rc))


def deny_path(cfg, rc):
    return os.path.join(cfg.data_dir, "deny", deny_hash(rc))


def is_whitelisted(cfg, rc):
    rp = canonical_path(rc)
    if cfg.whitelist_exact.get(rp):
        return True
    for p in cfg.whitelist_prefix:
        if rp.startswith(p):
            return True
    return False


def auth_status(cfg, rc):
    if is_whitelisted(cfg, rc):
        return 0
    if os.path.exists(deny_path(cfg, rc)):
        return 2
    ap = allow_path(cfg, rc)
    if os.path.exists(ap):
        try:
            with open(ap, "r", encoding="utf-8") as f:
                stored = f.read().strip()
            if canonical_path(stored) == canonical_path(rc):
                return 0
        except Exception:
            return 0
    return 1


def write_marker(path, rc):
    ensure_dir(os.path.dirname(path))
    with open(path, "w", encoding="utf-8") as f:
        f.write(canonical_path(rc) + "\n")


def remove_path_quiet(path):
    try:
        os.remove(path)
    except FileNotFoundError:
        pass
    except IsADirectoryError:
        shutil.rmtree(path, ignore_errors=True)


def find_rc_from(start_dir, cfg):
    d = canonical_path(start_dir)
    while True:
        envrc = os.path.join(d, ".envrc")
        dotenv = os.path.join(d, ".env")
        if os.path.isfile(envrc):
            return envrc
        if cfg.load_dotenv and os.path.isfile(dotenv):
            return dotenv
        parent = os.path.dirname(d)
        if parent == d:
            return None
        d = parent


def resolve_rc_arg(arg, cfg, for_default=False):
    if arg is None:
        rc = find_rc_from(os.getcwd(), cfg)
        if not rc:
            return None
        return rc
    p = canonical_path(arg)
    # Match lstat error wording for explicit missing path.
    try:
        st = os.lstat(p)
    except FileNotFoundError as ex:
        raise FileNotFoundError(f"lstat {p}: no such file or directory") from ex
    if stat.S_ISDIR(st.st_mode):
        envrc = os.path.join(p, ".envrc")
        dotenv = os.path.join(p, ".env")
        if os.path.isfile(envrc):
            return envrc
        if cfg.load_dotenv and os.path.isfile(dotenv):
            return dotenv
        # If a directory was given, search upward from it just like status.
        rc = find_rc_from(p, cfg)
        if rc:
            return rc
        return os.path.join(p, ".envrc")
    return p


def encode_obj(obj):
    raw = json.dumps(obj, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return STATE_PREFIX + base64.urlsafe_b64encode(zlib.compress(raw)).decode("ascii")


def decode_obj(s):
    if not s or not s.startswith(STATE_PREFIX):
        return None
    try:
        data = zlib.decompress(base64.urlsafe_b64decode(s[len(STATE_PREFIX):].encode("ascii")))
        return json.loads(data.decode("utf-8"))
    except Exception:
        return None


def build_watches(cfg, rc):
    items = []
    for p in [rc, allow_path(cfg, rc), deny_path(cfg, rc)]:
        try:
            mt = os.path.getmtime(p)
        except OSError:
            mt = 0
        items.append({"path": canonical_path(p), "mtime": mt})
    return encode_obj({"watches": items})


def decode_watches(s):
    obj = decode_obj(s)
    if not obj:
        return []
    return obj.get("watches", []) or []


def current_env_dict():
    return dict(os.environ)


def get_base_env(cur):
    st = decode_obj(cur.get("DIRENV_DIFF", ""))
    if st and isinstance(st.get("base"), dict):
        return {str(k): str(v) for k, v in st.get("base", {}).items()}
    # Fall back to current env without direnv bookkeeping.
    return {k: v for k, v in cur.items() if k not in INTERNAL_VARS and k != "DIRENV_IN_ENVRC"}


def sanitize_env_for_child(env):
    return {k: v for k, v in env.items() if "=" not in k and "\x00" not in k and "\x00" not in str(v)}


def dotenv_parse(path, initial=None):
    env = dict(initial or {})
    result = {}
    with open(path, "r", encoding="utf-8") as f:
        for rawline in f:
            line = rawline.rstrip("\n")
            stripped = line.strip()
            if not stripped or stripped.startswith("#"):
                continue
            if stripped.startswith("export "):
                stripped = stripped[7:].lstrip()
            m = re.match(r'^([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)$', stripped)
            if not m:
                raise ValueError(f"invalid line: {line}")
            key, val = m.group(1), m.group(2)
            val = parse_dotenv_value(val, env)
            env[key] = val
            result[key] = val
    return result, env


def parse_dotenv_value(s, env):
    s = s.strip()
    if s == "":
        return ""
    quote = s[0]
    if quote in ('"', "'"):
        out = []
        esc = False
        i = 1
        while i < len(s):
            c = s[i]
            if quote == '"' and esc:
                maps = {"n": "\n", "r": "\r", "t": "\t", "\\": "\\", '"': '"', "$": "$"}
                out.append(maps.get(c, c)); esc = False; i += 1; continue
            if quote == '"' and c == "\\":
                esc = True; i += 1; continue
            if c == quote:
                break
            out.append(c); i += 1
        val = "".join(out)
        if quote == '"':
            val = expand_vars(val, env)
        return val
    # Unquoted: strip comments starting at # and trim.
    if "#" in s:
        s = s.split("#", 1)[0]
    s = s.strip()
    return expand_vars(s, env)


def expand_vars(val, env):
    def repl(m):
        name = m.group(1) or m.group(2)
        return env.get(name, "")
    return re.sub(r'\$\{([A-Za-z_][A-Za-z0-9_]*)\}|\$([A-Za-z_][A-Za-z0-9_]*)', repl, val)


def py_single_quote(s):
    return "'" + str(s).replace("'", "''") + "'"


def fish_quote(s):
    return "'" + str(s).replace("\\", "\\\\").replace("'", "\\'") + "'"


def bash_ansi_quote(s):
    s = str(s)
    if s == "":
        return "''"
    if re.fullmatch(r"[0-9]+", s):
        return s
    # ANSI-C quote like direnv's shell exporter.
    out = "$'"
    for c in s:
        if c == "\\": out += "\\\\"
        elif c == "'": out += "\\'"
        elif c == "\n": out += "\\n"
        elif c == "\r": out += "\\r"
        elif c == "\t": out += "\\t"
        else:
            o = ord(c)
            if o < 32 or o == 127:
                out += "\\x%02x" % o
            else:
                out += c
    out += "'"
    return out


def tcsh_escape(s):
    s = str(s)
    if s == "":
        return "''"
    out = ""
    for c in s:
        if c == " ": out += "\\ "
        elif c == "#": out += '"#"'
        elif c in "\\'\";$`": out += "\\" + c
        elif c == "\n": out += "\\n"
        else: out += c
    return out


def ps_quote(s):
    return "'" + str(s).replace("'", "''") + "'"


def vim_quote(s):
    return "'" + str(s).replace("'", "''") + "'"


def compute_changes(current, target):
    changes = {}
    keys = set(current) | set(target)
    for k in sorted(keys):
        if k in IGNORED_DIFF_VARS:
            continue
        cv = current.get(k)
        tv_present = k in target
        if not tv_present:
            if k in current:
                changes[k] = None
        else:
            tv = str(target[k])
            if cv != tv:
                changes[k] = tv
    return changes


def render_exports(changes, shell):
    if not changes:
        return ""
    if shell in ("bash", "zsh"):
        parts = []
        for k in changes:
            v = changes[k]
            if v is None:
                parts.append(f"unset {k};")
            else:
                parts.append(f"export {k}={bash_ansi_quote(v)};")
        return "".join(parts)
    if shell == "fish":
        parts = []
        for k, v in changes.items():
            if v is None:
                parts.append(f"set -e -g {fish_quote(k)};")
            elif k == "PATH":
                vals = str(v).split(":") if str(v) else []
                parts.append("set -x -g PATH" + (" " + " ".join(fish_quote(x) for x in vals) if vals else "") + ";")
            else:
                parts.append(f"set -x -g {fish_quote(k)} {fish_quote(v)};")
        return "".join(parts)
    if shell == "tcsh":
        parts = []
        for k, v in changes.items():
            if v is None:
                parts.append(f"unsetenv {k} ;")
            elif k == "PATH":
                vals = str(v).split(":") if str(v) else []
                parts.append("set path = ( " + " ".join(tcsh_escape(x) for x in vals) + " );")
            else:
                parts.append(f"setenv {k} {tcsh_escape(v)} ;")
        return "".join(parts)
    if shell == "json":
        return json.dumps(changes, indent=2, sort_keys=True) + "\n"
    if shell in ("elvish", "murex"):
        return json.dumps(changes, sort_keys=True, separators=(",", ":")) + "\n"
    if shell == "pwsh":
        parts = []
        for k, v in changes.items():
            if v is None:
                parts.append(f"Remove-Item -LiteralPath 'env:/{k}';")
            else:
                parts.append(f"${{env:{k}}}={ps_quote(v)};")
        return "".join(parts)
    if shell == "vim":
        parts = []
        for k, v in changes.items():
            if v is None:
                parts.append(f"call setenv({vim_quote(k)},v:null)")
            else:
                parts.append(f"call setenv({vim_quote(k)},{vim_quote(v)})")
        return "\n".join(parts) + ("\n" if parts else "")
    if shell == "systemd":
        parts = []
        for k, v in changes.items():
            if v is not None:
                parts.append(f"{k}={v}")
        return "\n".join(parts) + ("\n" if parts else "")
    if shell == "gha":
        parts = []
        for k, v in changes.items():
            if v is None:
                continue
            delim = "ghadelimiter_" + hashlib.md5((k + "\0" + str(v)).encode()).hexdigest()
            parts.append(f"{k}<<{delim}\n{v}\n{delim}")
        return "\n".join(parts) + ("\n" if parts else "")
    if shell == "gzenv":
        return encode_obj({"env": changes}) + "\n"
    die(f"unknown target shell '{shell}'")


def diff_log(base, target):
    plus, minus, tilde = [], [], []
    keys = (set(base) | set(target)) - INTERNAL_VARS - IGNORED_DIFF_VARS
    for k in sorted(keys):
        if k.startswith("DIRENV_"):
            continue
        if k not in base and k in target:
            plus.append("+" + k)
        elif k in base and k not in target:
            minus.append("-" + k)
        elif base.get(k) != target.get(k):
            tilde.append("~" + k)
    return plus + minus + tilde


def stdlib_script(self_path=None):
    sp = self_path or find_self_path()
    # Original codebase has a larger stdlib. This clean-room implementation provides the public API.
    return f'''#!/usr/bin/env bash
#
# These are the commands available in an .envrc context
shopt -s nullglob
shopt -s extglob

direnv={shlex.quote(sp)}
direnv_config_dir="${{DIRENV_CONFIG:-${{XDG_CONFIG_HOME:-$HOME/.config}}/direnv}}"
export DIRENV_IN_ENVRC=1

log_status() {{ "$direnv" log --status "$1"; }}
log_error() {{ "$direnv" log --error "$1"; }}

strict_env() {{
  if (($#)); then ( set -euo pipefail; "$@" ); else set -euo pipefail; fi
}}
unstrict_env() {{
  if (($#)); then ( set +e +u +o pipefail; "$@" ); else set +e +u +o pipefail; fi
}}

direnv_layout_dir() {{ echo "${{direnv_layout_dir:-$PWD/.direnv}}"; }}

has() {{ type "$1" >/dev/null 2>&1; }}
join_args() {{ local IFS="$1"; shift; echo "$*"; }}

expand_path() {{
  local path="$1" rel="${{2:-$PWD}}"
  if [[ "$path" = /* ]]; then (cd / && cd "$(dirname "$path")" 2>/dev/null && printf '%s/%s\n' "$PWD" "$(basename "$path")");
  else (cd "$rel" 2>/dev/null && cd "$(dirname "$path")" 2>/dev/null && printf '%s/%s\n' "$PWD" "$(basename "$path")"); fi
}}

user_rel_path() {{
  local p="$1"
  case "$p" in "$HOME") echo '~';; "$HOME"/*) echo "~/${{p#$HOME/}}";; *) echo "$p";; esac
}}

find_up() {{
  local name="${{1:-.envrc}}" d="$PWD"
  while true; do
    if [[ -e "$d/$name" ]]; then echo "$d/$name"; return 0; fi
    [[ "$d" = / ]] && return 1
    d="$(dirname "$d")"
  done
}}

dotenv() {{
  local path="${{1:-.env}}"
  eval "$("$direnv" dotenv bash "$path")"
}}

dotenv_if_exists() {{ local path="${{1:-.env}}"; [[ -f "$path" ]] && dotenv "$path" || true; }}

