env_vars_required() {{
  local missing=0 v
  for v in "$@"; do
    if [[ -z "${{!v:-}}" ]]; then log_error "Required environment variable '$v' is missing"; missing=1; fi
  done
  return $missing
}}

_source_up() {{ local f="${{1:-.envrc}}" p; p=$(find_up "$f") || return 1; source_env "$p"; }}
