  eval "$("$direnv" apply_dump <(printf '%s' "$dump"))"
}}
direnv_apply_dump() {{ eval "$("$direnv" apply_dump "$1")"; }}

path_add() {{
  local var="$1" path; path=$(expand_path "$2") || return $?
  local old="${{!var:-}}"
  if [[ -n "$old" ]]; then export "$var=$path:$old"; else export "$var=$path"; fi
}}
PATH_add() {{ path_add PATH "$1"; }}
MANPATH_add() {{ path_add MANPATH "$1"; }}

PATH_rm() {{ path_rm PATH "$@"; }}
path_rm() {{
  local var="$1"; shift
  local IFS=: parts out p pat keep
  read -ra parts <<< "${{!var:-}}"
  out=()
  for p in "${{parts[@]}}"; do
    keep=1
    for pat in "$@"; do [[ "$p" == $pat ]] && keep=0; done
    ((keep)) && out+=("$p")
  done
  local joined="$(IFS=:; echo "${{out[*]}}")"
  export "$var=$joined"
}}

load_prefix() {{
  local p; p=$(expand_path "$1") || return $?
  PATH_add "$p/bin"
  path_add CPATH "$p/include"
  path_add LD_LIBRARY_PATH "$p/lib"
  path_add LIBRARY_PATH "$p/lib"
  MANPATH_add "$p/share/man"
  path_add PKG_CONFIG_PATH "$p/lib/pkgconfig"
}}

semver_search() {{
  local dir="$1" prefix="$2" partial="$3" best="" f v
  for f in "$dir"/$prefix*; do
    [[ -e "$f" ]] || continue
    v="${{f##*/$prefix}}"
    [[ "$v" == "$partial"* ]] || continue
    if [[ -z "$best" || "$v" > "$best" ]]; then best="$v"; fi
  done
  [[ -n "$best" ]] && echo "$best"
}}

layout() {{ local name="$1"; shift; "layout_$name" "$@"; }}
