def command_hook(args):
    shell = args[0] if args else ""
    selfp = find_self_path()
    if shell == "bash":
        sys.stdout.write(f'''
_direnv_hook() {{
  local previous_exit_status=$?;
  vars="$("{selfp}" export bash)";
  trap -- '' SIGINT;
  eval "$vars";
  trap - SIGINT;
  return $previous_exit_status;
}};
if [[ ";${{PROMPT_COMMAND[*]:-}};" != *";_direnv_hook;"* ]]; then
  if [[ "$(declare -p PROMPT_COMMAND 2>&1)" == "declare -a"* ]]; then
    PROMPT_COMMAND=(_direnv_hook "${{PROMPT_COMMAND[@]}}")
  else
    PROMPT_COMMAND="_direnv_hook${{PROMPT_COMMAND:+;$PROMPT_COMMAND}}"
  fi
fi
''')
    elif shell == "zsh":
        sys.stdout.write(f'''
_direnv_hook() {{
  vars="$("{selfp}" export zsh)"
  trap -- '' SIGINT
  eval "$vars"
  trap - SIGINT
}}
typeset -ag precmd_functions
if (( ! ${{precmd_functions[(I)_direnv_hook]}} )); then
  precmd_functions=(_direnv_hook $precmd_functions)
fi
typeset -ag chpwd_functions
if (( ! ${{chpwd_functions[(I)_direnv_hook]}} )); then
  chpwd_functions=(_direnv_hook $chpwd_functions)
fi
''')
    elif shell == "fish":
        sys.stdout.write(f'''
    function __direnv_export_eval --on-event fish_prompt;
        "{selfp}" export fish | source;

        if test "$direnv_fish_mode" != "disable_arrow";
            function __direnv_cd_hook --on-variable PWD;
                if test "$direnv_fish_mode" = "eval_after_arrow";
                    set -g __direnv_export_again 0;
                else;
                    "{selfp}" export fish | source;
                end;
            end;
        end;
    end;

    function __direnv_export_eval_2 --on-event fish_preexec;
        if set -q __direnv_export_again;
            set -e __direnv_export_again;
            "{selfp}" export fish | source;
            echo;
        end;

        functions --erase __direnv_cd_hook;
    end;
''')
    elif shell == "tcsh":
        sys.stdout.write(f"alias precmd 'eval `{selfp} export tcsh`'")
    elif shell == "elvish":
        sys.stdout.write(f'''## hook for direnv
set @edit:before-readline = $@edit:before-readline {{
\ttry {{
\t\tvar m = [("{selfp}" export elvish | from-json)]
\t\tif (> (count $m) 0) {{
\t\t\tset m = (all $m)
\t\t\tkeys $m | each {{ |k|
\t\t\t\tif $m[$k] {{
\t\t\t\t\tset-env $k $m[$k]
\t\t\t\t}} else {{
\t\t\t\t\tunset-env $k
\t\t\t\t}}
\t\t\t}}
\t\t}}
\t}} catch e {{
\t\techo $e
\t}}
}}
''')
    elif shell == "pwsh":
        sys.stdout.write(f'''using namespace System;
using namespace System.Management.Automation;

if ($PSVersionTable.PSVersion.Major -lt 7 -or ($PSVersionTable.PSVersion.Major -eq 7 -and $PSVersionTable.PSVersion.Minor -lt 2)) {{
    throw "direnv: PowerShell version $($PSVersionTable.PSVersion) does not meet the minimum required version 7.2!"
}}

$hook = [EventHandler[LocationChangedEventArgs]] {{
  param([object] $source, [LocationChangedEventArgs] $eventArgs)
  end {{
    $export = ({selfp} export pwsh) -join [Environment]::NewLine;
    if ($export) {{
      Invoke-Expression -Command $export;
    }}
  }}
}};
$currentAction = $ExecutionContext.SessionState.InvokeCommand.LocationChangedAction;
if ($currentAction) {{
  $ExecutionContext.SessionState.InvokeCommand.LocationChangedAction = [Delegate]::Combine($currentAction, $hook);
}}
else {{
  $ExecutionContext.SessionState.InvokeCommand.LocationChangedAction = $hook;
}};

''')
    elif shell == "murex":
        sys.stdout.write(f'''event: onPrompt direnv_hook=before {{
\t"{selfp}" export murex -> set exports
\tif {{ $exports != "" }} {{
\t\t$exports -> :json: formap key value {{
\t\t\tif {{ is-null value }} then {{
\t\t\t\t!export "$key"
\t\t\t}} else {{
\t\t\t\t$value -> export "$key"
\t\t\t}}
\t\t}}
\t}}
}}''')
    elif shell == "gha":
        die("Hook not implemented for GitHub Actions shell")
    elif shell == "vim":
        die("this feature is not supported. Install the direnv.vim plugin instead")
    elif shell == "gzenv":
        die("the gzenv shell doesn't support hooking")
    elif shell in ("json", "systemd"):
        die("this feature is not supported")
    else:
        die(f"unknown target shell '{shell}'")
    return 0


def command_dotenv(args):
    shell = "bash"
    path = ".env"
    if args:
        if args[0] in EXPORT_SHELLS:
            shell = args[0]
            if len(args) > 1:
                path = args[1]
        else:
            path = args[0]
    try:
        res, _env = dotenv_parse(path, dict(os.environ))
    except FileNotFoundError:
        die(f"open {path}: no such file or directory")
    except Exception as ex:
        die(str(ex))
    changes = {k: v for k, v in res.items()}
    sys.stdout.write(render_exports(changes, shell))
    return 0


def command_dump(args):
    shell = args[0] if args else "gzenv"
    env = {k: v for k, v in os.environ.items() if k not in IGNORED_DIFF_VARS or k == "PWD"}
    if shell == "gzenv":
        print(encode_obj({"env": env}))
    else:
        changes = dict(env)
        sys.stdout.write(render_exports(changes, shell))
    return 0


def read_dump_from_file(path):
    with open(path, "r", encoding="utf-8") as f:
        s = f.read().strip()
    obj = decode_obj(s)
    if obj and isinstance(obj.get("env"), dict):
        return obj["env"]
    try:
        return json.loads(s)
    except Exception:
        return {}


def command_apply_dump(args):
    if not args:
        die("missing FILE argument")
    env = read_dump_from_file(args[0])
    sys.stdout.write(render_exports(env, "bash"))
    return 0


def command_show_dump(args):
    if not args:
        die("missing DUMP argument")
    obj = decode_obj(args[0]) or {}
    print(json.dumps(obj, indent=2, sort_keys=True))
    return 0


def parse_sri(s):
    if not s.startswith("sha256-"):
        raise ValueError(f"sri: not a hash {s}")
    b64 = s[len("sha256-"):]
    try:
        raw = base64.b64decode(b64, validate=True)
    except Exception:
        raise ValueError(f"sri: not a hash {s}")
    if len(raw) != 32:
        raise ValueError(f"sri: not a hash {s}")
    return raw


def command_fetchurl(args):
    if not args:
        die("missing URL argument")
    url = args[0]
    integrity = args[1] if len(args) > 1 else None
    if integrity:
        try:
            expected = parse_sri(integrity)
        except ValueError as ex:
            die(str(ex))
    try:
        with urllib.request.urlopen(url) as r:
            data = r.read()
    except Exception as ex:
        die(str(ex))
    digest = hashlib.sha256(data).digest()
    sri = "sha256-" + base64.b64encode(digest).decode("ascii")
    cas = os.path.join(Config().cache_dir, "cas")
    ensure_dir(cas)
    hexname = digest.hex()
    outpath = os.path.join(cas, hexname)
    if not os.path.exists(outpath):
        fd, tmp = tempfile.mkstemp(prefix="tmp", dir=cas)
        with os.fdopen(fd, "wb") as f:
            f.write(data)
        os.chmod(tmp, 0o500)
        os.replace(tmp, outpath)
    if integrity:
        if digest != expected:
            die(f"hash mismatch. Expected '{integrity}' but got '{sri}'")
        print(outpath)
    else:
        # Non-tty stdout: hash only. TTY users get instructions.
        if sys.stdout.isatty():
            print(f"Found hash: {sri}\n")
            print("Invoke fetchurl again with the hash as an argument to get the disk location:\n")
            print(f"  direnv fetchurl {json.dumps(url)} {json.dumps(sri)}")
            print(f"  #=> {outpath}")
        else:
            print(sri)
    return 0


def command_watch(args, recursive=False):
    if not args:
        die("invalid arguments")
    shell = args[0] if args[0] in EXPORT_SHELLS else "bash"
    paths = args[1:] if args[0] in EXPORT_SHELLS else args
    watches = decode_watches(os.environ.get("DIRENV_WATCHES", ""))
    for p in paths:
        cp = canonical_path(p)
        if recursive and os.path.isdir(cp):
            for root, dirs, files in os.walk(cp):
                for name in files:
                    fp = os.path.join(root, name)
                    try: mt = os.path.getmtime(fp)
                    except OSError: mt = 0
                    watches.append({"path": fp, "mtime": mt})
        else:
            try: mt = os.path.getmtime(cp)
            except OSError: mt = 0
            watches.append({"path": cp, "mtime": mt})
    sys.stdout.write(render_exports({"DIRENV_WATCHES": encode_obj({"watches": watches})}, shell))
    return 0


def command_watch_list(args):
    shell = args[0] if args and args[0] in EXPORT_SHELLS else "bash"
    watches = []
    for line in sys.stdin:
        line = line.rstrip("\n")
        if not line: continue
        parts = line.split(" ", 1)
        if len(parts) == 2:
            try: mt = float(parts[0])
            except ValueError: mt = 0
            watches.append({"mtime": mt, "path": canonical_path(parts[1])})
    sys.stdout.write(render_exports({"DIRENV_WATCHES": encode_obj({"watches": watches})}, shell))
    return 0


def command_watch_print(args):
    null = args and args[0] == "--null"
    sep = "\0" if null else "\n"
    paths = [w.get("path", "") for w in decode_watches(os.environ.get("DIRENV_WATCHES", ""))]
    if paths:
        sys.stdout.write(sep.join(paths) + sep)
    return 0


def command_current(args):
    if not args:
        die("missing PATH argument")
    p = canonical_path(args[0])
    for w in decode_watches(os.environ.get("DIRENV_WATCHES", "")):
        if canonical_path(w.get("path", "")) == p:
            try: mt = os.path.getmtime(p)
            except OSError: mt = 0
            return 0 if abs(mt - float(w.get("mtime", 0))) < 1e-6 else 1
    die(f"File \"{p}\" is unknown")


def command_check_required(args):
    # Compatibility no-op: required files are considered allowed if they exist or have allow markers.
    return 0


def main(argv):
    if len(argv) == 0 or argv[0] in ("help", "--help"):
        return command_help(argv[1:] if argv and argv[0] == "help" else [])
    if argv[0] == "--version":
        return command_version([])
    cmd, args = argv[0], argv[1:]
    try:
        if cmd in ("allow", "permit", "grant"):
            return command_allow(args, deny=False)
        if cmd in ("deny", "block", "disallow", "revoke"):
            return command_allow(args, deny=True)
        if cmd == "edit":
            return command_edit(args)
        if cmd == "exec":
            return command_exec(args)
        if cmd == "export":
            return command_export(args)
        if cmd == "fetchurl":
            return command_fetchurl(args)
        if cmd == "hook":
            return command_hook(args)
        if cmd == "prune":
            return command_prune(args)
        if cmd == "reload":
            return command_reload(args)
        if cmd == "status":
            return command_status(args)
        if cmd == "stdlib":
            sys.stdout.write(stdlib_script(find_self_path()))
            return 0
        if cmd == "version":
            return command_version(args)
        if cmd == "log":
            return command_log(args)
        # private commands
        if cmd == "dotenv":
            return command_dotenv(args)
        if cmd == "dump":
            return command_dump(args)
        if cmd == "apply_dump":
            return command_apply_dump(args)
        if cmd == "show_dump":
            return command_show_dump(args)
        if cmd == "watch":
            return command_watch(args, recursive=False)
        if cmd == "watch-dir":
            return command_watch(args, recursive=True)
        if cmd == "watch-list":
            return command_watch_list(args)
        if cmd == "watch-print":
            return command_watch_print(args)
        if cmd == "current":
            return command_current(args)
        if cmd == "check-required":
            return command_check_required(args)
        die(f"command \"{sys.argv[0]} {cmd}\" not found")
    except BrokenPipeError:
        return 1


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
